package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.apache.commons.cli.CommandLine;
import org.apache.commons.cli.Option;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CommandLine_hasOption_TriageGen1Test {

    private Option opt1;
    private Option opt2;
    private CommandLine commandLine;

    @Before
    public void setUp() throws ParseException {
        opt1 = Option.builder("a").desc("option a").build();
        opt2 = Option.builder("b").desc("option b").build();

        // Since CommandLine is usually produced by a Parser, 
        // we simulate the state by using a Parser or mocking if necessary.
        // In Apache Commons CLI, CommandLine is typically immutable after parsing.
        // We use Options to build the context.
        Options options = new Options();
        options.addOption(opt1);
        options.addOption(opt2);

        // We use a dummy parser to create a real CommandLine instance
        OptionsParser parser = new OptionsParser();
        // We simulate command line arguments: -a -b
        commandLine = parser.parse(options, new String[]{"-a", "-b"});
    }

    @Test
    public void testHasOption_WithExistingOption() {
        assertTrue("Should return true for option 'a'", commandLine.hasOption("a"));
        assertTrue("Should return true for option 'b'", commandLine.hasOption("b"));
    }

    @Test
    public void testHasOption_WithNonExistingOption() {
        assertFalse("Should return false for non-existent option 'c'", commandLine.hasOption("c"));
        assertFalse("Should return false for null", commandLine.hasOption(null));
        assertFalse("Should return false for empty string", commandLine.hasOption(""));
    }

    @Test
    public void testHasOption_WithOptionThatExistsInDefinitionButNotInCommand() {
        Options options = new Options();
        options.addOption(opt1);
        options.addOption(opt2);

        // Command line only contains 'a'
        CommandLine cmd = new OptionsParser().parse(options, new String[]{"-a"});

        assertTrue("Should return true for 'a'", cmd.hasOption("a"));
        assertFalse("Should return false for 'b' because it wasn't provided in arguments", cmd.hasOption("b"));
    }
}
